const FILES={mouth:'pampanaa-mouth.mp3',band:'impactGeneric_light_000.ogg',kick:'football-kick.mp3',clap:'handclap.mp3',call:'whistle.mp3',goal:'applause.mp3',point:'handclap.mp3',miss:'impactSoft_medium_000.ogg',stone:'impactWood_light_000.ogg',swing:'impactGeneric_light_000.ogg',jump:'footstep-dirt-1.mp3',step1:'footstep-dirt-1.mp3',step2:'footstep-dirt-2.mp3',step3:'footstep-dirt-3.mp3',ambience:'outdoor-ambience.ogg'};
export class Soundscape{
 constructor(){this.enabled=true;this.active=false;this.buffers={};this.raw={};this.context=null;this.ambient=null;}
 async preload(){await Promise.all(Object.entries(FILES).map(async([key,name])=>{try{const r=await fetch('assets/audio/'+name);if(r.ok)this.raw[key]=await r.arrayBuffer();}catch{}}));}
 async unlock(){if(!this.context){this.context=new (window.AudioContext||window.webkitAudioContext)();this.master=this.context.createGain();this.master.gain.value=this.enabled?.65:0;this.master.connect(this.context.destination);this.recordDestination=this.context.createMediaStreamDestination();this.master.connect(this.recordDestination);await Promise.all(Object.entries(this.raw).map(async([key,data])=>{try{this.buffers[key]=await this.context.decodeAudioData(data.slice(0));}catch{}}));}await this.context.resume();this.setActive(this.active);}
 setEnabled(enabled){this.enabled=enabled;if(this.master)this.master.gain.setTargetAtTime(enabled?.65:0,this.context.currentTime,.05);}
 setActive(active){this.active=active;if(!this.context||!this.buffers.ambience)return;if(active&&!this.ambient){const source=this.context.createBufferSource(),gain=this.context.createGain();source.buffer=this.buffers.ambience;source.loop=true;gain.gain.value=.21;source.connect(gain);gain.connect(this.master);source.start();this.ambient=source;}else if(!active&&this.ambient){this.ambient.stop();this.ambient=null;}}
 play(type){if(!this.enabled||!this.context)return;const key=type==='step'?'step'+(1+Math.floor(Math.random()*3)):type;const buffer=this.buffers[key]||this.buffers.stone;if(!buffer)return;const source=this.context.createBufferSource(),gain=this.context.createGain();source.buffer=buffer;source.playbackRate.value=type==='call'?1:.96+Math.random()*.08;gain.gain.value={step:.34,goal:.65,call:.38,point:.25,clap:.48,kick:.7,stone:.45}[type]||.34;source.connect(gain);gain.connect(this.master);source.start();source.onended=()=>{source.disconnect();gain.disconnect();};}
}
